var n=`0007-varenyky-with-cherries`;var t=`world-0007`;var o=`UA`;var r=`eastern-europe`;var a=4;var s=62;var g={en:`Varenyky with Cherries`,ua:`Вареники з вишнями`};var l={en:`A classic dish from Ukraine, featuring chicken egg, sour cherry, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: куряче яйце, кисла вишня, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,480,`g`],[`water`,225,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,3,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`sour-cherry`,500,`g`],[`white-granulated-sugar`,75,`g`],[`potato-starch`,15,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:25,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 5 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 5 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:5,i:[[`water`,1500,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,100,`g`]]}];var u={slug:n,id:t,country:`UA`,region:r,servings:4,minutes:62,title:g,text:l,steps:h};export{o as country,u as default,t as id,s as minutes,r as region,a as servings,n as slug,h as steps,l as text,g as title};